import sys
from collections import defaultdict, deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    adj = defaultdict(list)
    edges = []

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        edges.append((u, v))

    # Function to check if a graph has a cycle using Kahn's algorithm (topological sort)
    # Returns True if acyclic, False if cyclic
    def is_acyclic(graph_adj, num_vertices):
        in_degree = [0] * (num_vertices + 1)
        for u in graph_adj:
            for v in graph_adj[u]:
                in_degree[v] += 1

        queue = deque()
        for i in range(1, num_vertices + 1):
            if in_degree[i] == 0:
                queue.append(i)

        count = 0
        while queue:
            u = queue.popleft()
            count += 1
            for v in graph_adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        return count == num_vertices

    # First, check if the original graph is already acyclic
    if is_acyclic(adj, n):
        print("YES")
        return

    # If there is a cycle, we need to find one cycle and try removing each edge in it.
    # If removing any edge in the cycle makes the graph acyclic, then YES.
    # Otherwise, NO.

    # Find a cycle using DFS
    # States: 0 = unvisited, 1 = visiting, 2 = visited
    state = [0] * (n + 1)
    parent_edge = {} # Maps node -> (u, v) where u->v is the edge leading to node

    cycle_edges = []
    found_cycle = False

    def dfs(u):
        nonlocal found_cycle
        state[u] = 1
        for v in adj[u]:
            if state[v] == 1:
                # Found a back edge, which means a cycle
                found_cycle = True
                # Reconstruct the cycle
                curr = v
                cycle_edges.append((u, v))
                while curr != u:
                    p_u, p_v = parent_edge[curr]
                    cycle_edges.append((p_u, p_v))
                    curr = p_u
                return
            elif state[v] == 0:
                parent_edge[v] = (u, v)
                dfs(v)
                if found_cycle:
                    return
        state[u] = 2

    for i in range(1, n + 1):
        if state[i] == 0:
            dfs(i)
            if found_cycle:
                break

    if not found_cycle:
        # Should not happen if is_acyclic returned False, but safe guard
        print("YES")
        return

    # Try removing each edge in the found cycle
    for u_rem, v_rem in cycle_edges:
        # Create a temporary adjacency list without this edge
        # To avoid copying the whole list, we can modify and revert, 
        # or just build a new one for the check. Given N=500, building new is fine.

        temp_adj = defaultdict(list)
        for x in adj:
            for y in adj[x]:
                if not (x == u_rem and y == v_rem):
                    temp_adj[x].append(y)

        if is_acyclic(temp_adj, n):
            print("YES")
            return

    print("NO")

if __name__ == "__main__":
    solve()
